text:
Use `pg` library (`node-postgres`). Best pool config:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT ?? 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                  // max connections (default 10)
  min: 2,                   // keep alive idle connections
  idleTimeoutMillis: 30000, // kill idle conn after 30s
  connectionTimeoutMillis: 2000, // fail fast if can't get conn in 2s

  // SSL (prod)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true, ca: process.env.DB_CA_CERT }
    : false,
});

// Catch idle conn errors — else crashes process
pool.on('error', (err, client) => {
  console.error('Idle client error', err.message);
});

// Wrapper — handles acquire + release automatically
export async function query(text, params) {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    console.debug('Query executed', { text, duration: Date.now() - start, rows: result.rowCount });
    return result;
  } catch (err) {
    console.error('Query failed', { text, err: err.message });
    throw err;
  }
}

// Use when need transaction or multiple queries on same conn
export async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

// Graceful shutdown
export async function closePool() {
  await pool.end();
}
```

**Usage:**

```javascript
// Simple query
const { rows } = await query('SELECT * FROM users WHERE id = $1', [userId]);

// Transaction
await withClient(async (client) => {
  await client.query('BEGIN');
  try {
    await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
    await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
});
```

**Key decisions:**

| Setting | Why |
|---|---|
| `max: 20` | Match Postgres `max_connections` / num services. Default 10 too low under load |
| `min: 2` | Avoid cold-start latency on first requests |
| `connectionTimeoutMillis: 2000` | Fail fast vs hang. Tune per SLA |
| `pool.on('error')` | **Required.** Unhandled idle error = process crash |
| `client.release()` in `finally` | Leak = pool exhaustion = all requests hang |

**Shutdown** — wire to process signals:

```javascript
process.on('SIGTERM', async () => {
  await closePool();
  process.exit(0);
});
```
